window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0e6c9c7c2c3b212a"]={"versions": [{"id": "FIG-0e6c9c7c2c3b212a", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm / Protokollablaufdiagramm (Message Sequence Chart) auf Transport-Layer-Ebene.</li>\n<li><strong>Architektur-Einordnung:</strong> Spezifikation des AUTOSAR Classic FlexRay AR Transport Layer (<code>FrArTp</code>, Schicht zwischen <code>PduR</code> und <code>FrIf</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des unsegmentierten 1:1-Punkt-zu-Punkt-Datentransfers (Unicast) unter der Betriebsart <em>„Acknowledgement with Retry“</em> bei primärem Übertragungsfehler. Dargestellt ist der Fehlertoleranzpfad: Ein initialer Fehler beim Empfänger führt zu einem NACK (<code>Negative Acknowledge</code>), woraufhin der Sender eine automatische Wiederholung (<code>SF</code>-Retransmission) ausführt, die mit einem ACK (<code>Positive Acknowledge</code>) quittiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsteilnehmer (Lifelines):</strong></li>\n<li><code>Sender</code>: Sende-Instanz des FlexRay AR Transport Layers (<code>FrArTp</code>).</li>\n<li><code>Receiver</code>: Empfangende Peer-Instanz des <code>FrArTp</code> auf der Ziel-ECU.</li>\n<li><strong>Protokoll-Dateneinheiten (N-PDUs / N-PCIs):</strong></li>\n<li><code>SF</code> (Single Frame): Unsegmentierte N-PDU. Enthält neben den Nutzdaten (SDU) den N-PCI-Header (Kennzeichnung als <code>SF</code> inklusive Datenlängenangabe).</li>\n<li><code>AF</code> (Acknowledge Frame): Flusssteuerungs- und Bestätigungs-PDU der Gegenstelle.</li>\n<li><code>AF (Negative Acknowledge)</code>: NACK-Codierung im N-PCI; signalisiert Empfangs- oder Pufferungsfehler (z. B. temporäre Ressourcenerschöpfung).</li>\n<li><code>AF (Positive Acknowledge)</code>: ACK-Codierung im N-PCI; signalisiert den fehlerfreien Empfang und die Bereitstellung der Daten an die obere Schicht.</li>\n<li><strong>Stack-Schnittstellen (implizit beteiligt):</strong></li>\n<li>Obere Schicht (<code>PduR</code>): <code>PduR_FrArTpTxConfirmation()</code>, <code>PduR_FrArTpRxIndication()</code>.</li>\n<li>Untere Schicht (<code>FrIf</code>): <code>FrIf_Transmit()</code>, Bestätigung über <code>FrArTp_TxConfirmation()</code>, Empfang via <code>FrArTp_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Transfer (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender initiiert nach Erhalt einer Sendeanforderung (<code>FrArTp_Transmit</code>) die Übertragung einer unsegmentierten SDU mittels Single Frame (<code>SF</code>) über das FlexRay-Interface.</li>\n<li>Der Sender startet den Timeout-Timer für die Bestätigungserwartung (Timeout $A_s$ bzw. Bestätigungstimer).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfängerseitiger Fehler & NACK (<code>AF Negative Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger detektiert den <code>SF</code>, kann die Nachricht jedoch nicht ordnungsgemäß verarbeiten/puffern.</li>\n<li>Der Empfänger generiert einen <code>AF</code> mit negativem Statusflag (<code>Negative Acknowledge</code>) und sendet diesen an den Sender zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auswertung & Retransmission (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender empfängt die negative <code>AF</code>.</li>\n<li>Aufgrund der Moduskonfiguration <em>Acknowledgement with Retry</em> inkrementiert der Sender seinen internen Wiederholungszähler (Retry-Counter).</li>\n<li>Solange die maximale Anzahl konfigurierter Versuche (<code>FrArTpMaxRetries</code>) nicht überschritten ist, wird der identische <code>SF</code> erneut asynchron übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erfolgreiche Verarbeitung & Quittierung (<code>AF Positive Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger nimmt den retransmittierten <code>SF</code> an, puffert ihn erfolgreich und sendet eine <code>AF</code> mit positivem Bestätigungsstatus (<code>Positive Acknowledge</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender stoppt den Überwachungstimer und meldet den erfolgreichen Transfer mit <code>NTFRSLT_OK</code> an den <code>PduR</code>.</li>\n<li><em>Abbruchkriterium:</em> Scheitert auch der zweite (oder jeder weitere) Versuch und der Retry-Zähler erreicht das Limit (<code>FrArTpMaxRetries</code>), bricht der Sender die Übertragung ab und signalisiert der oberen Schicht einen Fehler (<code>NTFRSLT_E_NOT_OK</code> / Retry-Limit erreicht).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Pufferhaltung im Treiber/Stack:</strong></li>\n<li>Da der <code>Sender</code> bei konfigurierter Retry-Funktion die SDU nach einem NACK erneut senden muss, darf der Sendepuffer der oberen Schicht (<code>PduR</code>/Applikation) <strong>nicht</strong> direkt nach dem ersten <code>FrIf_Transmit()</code> bzw. dessen lokaler Bestätigung freigegeben werden. Der Puffer muss gebunden bleiben, bis entweder die positive <code>AF</code> empfangen wird oder die maximale Wiederholungsanzahl/der Timer erschöpft ist.</li>\n<li><strong>Konfigurationsparameter (ECUC):</strong></li>\n<li>Quittierungsmodus: <code>FrArTpAckType</code> = <code>ACK_WITH_RETRY</code> für die betroffene Verbindungsbeziehung (<code>FrArTpConnection</code>).</li>\n<li>Wiederholungsbegrenzung: <code>FrArTpMaxRetries</code> muss sorgfältig auf die Latenzanforderungen des Gesamtsystems abgestimmt werden, um Blockaden im Sendekanal zu vermeiden.</li>\n<li>Timer-Konfiguration: Abstimmung von Timeout-Parametern ($A_s$, $A_r$, $B_s$) auf das FlexRay-Kommunikationsraster (Cycle-Time, statisches/dynamisches Segment).</li>\n<li><strong>FlexRay-Slot- und Bandbreiten-Design:</strong></li>\n<li>Jede <code>AF</code> (insbesondere NACK gefolgt von erneutem SF und finaler ACK) belegt Bandbreite im FlexRay-Zyklus. Bei zyklischen PDUs kann eine Kette von NACKs und Retries zu Slot-Verzug (Jitter) und Pufferstau in der <code>FrArTp_MainFunction()</code> führen.</li>\n</ul>"}, {"id": "FIG-3f16eccfd444835a", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm / Protokollablaufdiagramm (Message Sequence Chart) auf Transport-Layer-Ebene.</li>\n<li><strong>Architektur-Einordnung:</strong> Spezifikation des AUTOSAR Classic FlexRay AR Transport Layer (<code>FrArTp</code>, Schicht zwischen <code>PduR</code> und <code>FrIf</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des unsegmentierten 1:1-Punkt-zu-Punkt-Datentransfers (Unicast) unter der Betriebsart <em>„Acknowledgement with Retry“</em> bei primärem Übertragungsfehler. Dargestellt ist der Fehlertoleranzpfad: Ein initialer Fehler beim Empfänger führt zu einem NACK (<code>Negative Acknowledge</code>), woraufhin der Sender eine automatische Wiederholung (<code>SF</code>-Retransmission) ausführt, die mit einem ACK (<code>Positive Acknowledge</code>) quittiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsteilnehmer (Lifelines):</strong></li>\n<li><code>Sender</code>: Sende-Instanz des FlexRay AR Transport Layers (<code>FrArTp</code>).</li>\n<li><code>Receiver</code>: Empfangende Peer-Instanz des <code>FrArTp</code> auf der Ziel-ECU.</li>\n<li><strong>Protokoll-Dateneinheiten (N-PDUs / N-PCIs):</strong></li>\n<li><code>SF</code> (Single Frame): Unsegmentierte N-PDU. Enthält neben den Nutzdaten (SDU) den N-PCI-Header (Kennzeichnung als <code>SF</code> inklusive Datenlängenangabe).</li>\n<li><code>AF</code> (Acknowledge Frame): Flusssteuerungs- und Bestätigungs-PDU der Gegenstelle.</li>\n<li><code>AF (Negative Acknowledge)</code>: NACK-Codierung im N-PCI; signalisiert Empfangs- oder Pufferungsfehler (z. B. temporäre Ressourcenerschöpfung).</li>\n<li><code>AF (Positive Acknowledge)</code>: ACK-Codierung im N-PCI; signalisiert den fehlerfreien Empfang und die Bereitstellung der Daten an die obere Schicht.</li>\n<li><strong>Stack-Schnittstellen (implizit beteiligt):</strong></li>\n<li>Obere Schicht (<code>PduR</code>): <code>PduR_FrArTpTxConfirmation()</code>, <code>PduR_FrArTpRxIndication()</code>.</li>\n<li>Untere Schicht (<code>FrIf</code>): <code>FrIf_Transmit()</code>, Bestätigung über <code>FrArTp_TxConfirmation()</code>, Empfang via <code>FrArTp_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Transfer (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender initiiert nach Erhalt einer Sendeanforderung (<code>FrArTp_Transmit</code>) die Übertragung einer unsegmentierten SDU mittels Single Frame (<code>SF</code>) über das FlexRay-Interface.</li>\n<li>Der Sender startet den Timeout-Timer für die Bestätigungserwartung (Timeout $A_s$ bzw. Bestätigungstimer).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfängerseitiger Fehler & NACK (<code>AF Negative Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger detektiert den <code>SF</code>, kann die Nachricht jedoch nicht ordnungsgemäß verarbeiten/puffern.</li>\n<li>Der Empfänger generiert einen <code>AF</code> mit negativem Statusflag (<code>Negative Acknowledge</code>) und sendet diesen an den Sender zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auswertung & Retransmission (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender empfängt die negative <code>AF</code>.</li>\n<li>Aufgrund der Moduskonfiguration <em>Acknowledgement with Retry</em> inkrementiert der Sender seinen internen Wiederholungszähler (Retry-Counter).</li>\n<li>Solange die maximale Anzahl konfigurierter Versuche (<code>FrArTpMaxRetries</code>) nicht überschritten ist, wird der identische <code>SF</code> erneut asynchron übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erfolgreiche Verarbeitung & Quittierung (<code>AF Positive Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger nimmt den retransmittierten <code>SF</code> an, puffert ihn erfolgreich und sendet eine <code>AF</code> mit positivem Bestätigungsstatus (<code>Positive Acknowledge</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender stoppt den Überwachungstimer und meldet den erfolgreichen Transfer mit <code>NTFRSLT_OK</code> an den <code>PduR</code>.</li>\n<li><em>Abbruchkriterium:</em> Scheitert auch der zweite (oder jeder weitere) Versuch und der Retry-Zähler erreicht das Limit (<code>FrArTpMaxRetries</code>), bricht der Sender die Übertragung ab und signalisiert der oberen Schicht einen Fehler (<code>NTFRSLT_E_NOT_OK</code> / Retry-Limit erreicht).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Pufferhaltung im Treiber/Stack:</strong></li>\n<li>Da der <code>Sender</code> bei konfigurierter Retry-Funktion die SDU nach einem NACK erneut senden muss, darf der Sendepuffer der oberen Schicht (<code>PduR</code>/Applikation) <strong>nicht</strong> direkt nach dem ersten <code>FrIf_Transmit()</code> bzw. dessen lokaler Bestätigung freigegeben werden. Der Puffer muss gebunden bleiben, bis entweder die positive <code>AF</code> empfangen wird oder die maximale Wiederholungsanzahl/der Timer erschöpft ist.</li>\n<li><strong>Konfigurationsparameter (ECUC):</strong></li>\n<li>Quittierungsmodus: <code>FrArTpAckType</code> = <code>ACK_WITH_RETRY</code> für die betroffene Verbindungsbeziehung (<code>FrArTpConnection</code>).</li>\n<li>Wiederholungsbegrenzung: <code>FrArTpMaxRetries</code> muss sorgfältig auf die Latenzanforderungen des Gesamtsystems abgestimmt werden, um Blockaden im Sendekanal zu vermeiden.</li>\n<li>Timer-Konfiguration: Abstimmung von Timeout-Parametern ($A_s$, $A_r$, $B_s$) auf das FlexRay-Kommunikationsraster (Cycle-Time, statisches/dynamisches Segment).</li>\n<li><strong>FlexRay-Slot- und Bandbreiten-Design:</strong></li>\n<li>Jede <code>AF</code> (insbesondere NACK gefolgt von erneutem SF und finaler ACK) belegt Bandbreite im FlexRay-Zyklus. Bei zyklischen PDUs kann eine Kette von NACKs und Retries zu Slot-Verzug (Jitter) und Pufferstau in der <code>FrArTp_MainFunction()</code> führen.</li>\n</ul>"}, {"id": "FIG-e39333f763ecaba8", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm / Protokollablaufdiagramm (Message Sequence Chart) auf Transport-Layer-Ebene.</li>\n<li><strong>Architektur-Einordnung:</strong> Spezifikation des AUTOSAR Classic FlexRay AR Transport Layer (<code>FrArTp</code>, Schicht zwischen <code>PduR</code> und <code>FrIf</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des unsegmentierten 1:1-Punkt-zu-Punkt-Datentransfers (Unicast) unter der Betriebsart <em>„Acknowledgement with Retry“</em> bei primärem Übertragungsfehler. Dargestellt ist der Fehlertoleranzpfad: Ein initialer Fehler beim Empfänger führt zu einem NACK (<code>Negative Acknowledge</code>), woraufhin der Sender eine automatische Wiederholung (<code>SF</code>-Retransmission) ausführt, die mit einem ACK (<code>Positive Acknowledge</code>) quittiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsteilnehmer (Lifelines):</strong></li>\n<li><code>Sender</code>: Sende-Instanz des FlexRay AR Transport Layers (<code>FrArTp</code>).</li>\n<li><code>Receiver</code>: Empfangende Peer-Instanz des <code>FrArTp</code> auf der Ziel-ECU.</li>\n<li><strong>Protokoll-Dateneinheiten (N-PDUs / N-PCIs):</strong></li>\n<li><code>SF</code> (Single Frame): Unsegmentierte N-PDU. Enthält neben den Nutzdaten (SDU) den N-PCI-Header (Kennzeichnung als <code>SF</code> inklusive Datenlängenangabe).</li>\n<li><code>AF</code> (Acknowledge Frame): Flusssteuerungs- und Bestätigungs-PDU der Gegenstelle.</li>\n<li><code>AF (Negative Acknowledge)</code>: NACK-Codierung im N-PCI; signalisiert Empfangs- oder Pufferungsfehler (z. B. temporäre Ressourcenerschöpfung).</li>\n<li><code>AF (Positive Acknowledge)</code>: ACK-Codierung im N-PCI; signalisiert den fehlerfreien Empfang und die Bereitstellung der Daten an die obere Schicht.</li>\n<li><strong>Stack-Schnittstellen (implizit beteiligt):</strong></li>\n<li>Obere Schicht (<code>PduR</code>): <code>PduR_FrArTpTxConfirmation()</code>, <code>PduR_FrArTpRxIndication()</code>.</li>\n<li>Untere Schicht (<code>FrIf</code>): <code>FrIf_Transmit()</code>, Bestätigung über <code>FrArTp_TxConfirmation()</code>, Empfang via <code>FrArTp_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Transfer (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender initiiert nach Erhalt einer Sendeanforderung (<code>FrArTp_Transmit</code>) die Übertragung einer unsegmentierten SDU mittels Single Frame (<code>SF</code>) über das FlexRay-Interface.</li>\n<li>Der Sender startet den Timeout-Timer für die Bestätigungserwartung (Timeout $A_s$ bzw. Bestätigungstimer).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfängerseitiger Fehler & NACK (<code>AF Negative Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger detektiert den <code>SF</code>, kann die Nachricht jedoch nicht ordnungsgemäß verarbeiten/puffern.</li>\n<li>Der Empfänger generiert einen <code>AF</code> mit negativem Statusflag (<code>Negative Acknowledge</code>) und sendet diesen an den Sender zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auswertung & Retransmission (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender empfängt die negative <code>AF</code>.</li>\n<li>Aufgrund der Moduskonfiguration <em>Acknowledgement with Retry</em> inkrementiert der Sender seinen internen Wiederholungszähler (Retry-Counter).</li>\n<li>Solange die maximale Anzahl konfigurierter Versuche (<code>FrArTpMaxRetries</code>) nicht überschritten ist, wird der identische <code>SF</code> erneut asynchron übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erfolgreiche Verarbeitung & Quittierung (<code>AF Positive Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger nimmt den retransmittierten <code>SF</code> an, puffert ihn erfolgreich und sendet eine <code>AF</code> mit positivem Bestätigungsstatus (<code>Positive Acknowledge</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender stoppt den Überwachungstimer und meldet den erfolgreichen Transfer mit <code>NTFRSLT_OK</code> an den <code>PduR</code>.</li>\n<li><em>Abbruchkriterium:</em> Scheitert auch der zweite (oder jeder weitere) Versuch und der Retry-Zähler erreicht das Limit (<code>FrArTpMaxRetries</code>), bricht der Sender die Übertragung ab und signalisiert der oberen Schicht einen Fehler (<code>NTFRSLT_E_NOT_OK</code> / Retry-Limit erreicht).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Pufferhaltung im Treiber/Stack:</strong></li>\n<li>Da der <code>Sender</code> bei konfigurierter Retry-Funktion die SDU nach einem NACK erneut senden muss, darf der Sendepuffer der oberen Schicht (<code>PduR</code>/Applikation) <strong>nicht</strong> direkt nach dem ersten <code>FrIf_Transmit()</code> bzw. dessen lokaler Bestätigung freigegeben werden. Der Puffer muss gebunden bleiben, bis entweder die positive <code>AF</code> empfangen wird oder die maximale Wiederholungsanzahl/der Timer erschöpft ist.</li>\n<li><strong>Konfigurationsparameter (ECUC):</strong></li>\n<li>Quittierungsmodus: <code>FrArTpAckType</code> = <code>ACK_WITH_RETRY</code> für die betroffene Verbindungsbeziehung (<code>FrArTpConnection</code>).</li>\n<li>Wiederholungsbegrenzung: <code>FrArTpMaxRetries</code> muss sorgfältig auf die Latenzanforderungen des Gesamtsystems abgestimmt werden, um Blockaden im Sendekanal zu vermeiden.</li>\n<li>Timer-Konfiguration: Abstimmung von Timeout-Parametern ($A_s$, $A_r$, $B_s$) auf das FlexRay-Kommunikationsraster (Cycle-Time, statisches/dynamisches Segment).</li>\n<li><strong>FlexRay-Slot- und Bandbreiten-Design:</strong></li>\n<li>Jede <code>AF</code> (insbesondere NACK gefolgt von erneutem SF und finaler ACK) belegt Bandbreite im FlexRay-Zyklus. Bei zyklischen PDUs kann eine Kette von NACKs und Retries zu Slot-Verzug (Jitter) und Pufferstau in der <code>FrArTp_MainFunction()</code> führen.</li>\n</ul>"}, {"id": "FIG-ac649915c40bb616", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm / Protokollablaufdiagramm (Message Sequence Chart) auf Transport-Layer-Ebene.</li>\n<li><strong>Architektur-Einordnung:</strong> Spezifikation des AUTOSAR Classic FlexRay AR Transport Layer (<code>FrArTp</code>, Schicht zwischen <code>PduR</code> und <code>FrIf</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des unsegmentierten 1:1-Punkt-zu-Punkt-Datentransfers (Unicast) unter der Betriebsart <em>„Acknowledgement with Retry“</em> bei primärem Übertragungsfehler. Dargestellt ist der Fehlertoleranzpfad: Ein initialer Fehler beim Empfänger führt zu einem NACK (<code>Negative Acknowledge</code>), woraufhin der Sender eine automatische Wiederholung (<code>SF</code>-Retransmission) ausführt, die mit einem ACK (<code>Positive Acknowledge</code>) quittiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsteilnehmer (Lifelines):</strong></li>\n<li><code>Sender</code>: Sende-Instanz des FlexRay AR Transport Layers (<code>FrArTp</code>).</li>\n<li><code>Receiver</code>: Empfangende Peer-Instanz des <code>FrArTp</code> auf der Ziel-ECU.</li>\n<li><strong>Protokoll-Dateneinheiten (N-PDUs / N-PCIs):</strong></li>\n<li><code>SF</code> (Single Frame): Unsegmentierte N-PDU. Enthält neben den Nutzdaten (SDU) den N-PCI-Header (Kennzeichnung als <code>SF</code> inklusive Datenlängenangabe).</li>\n<li><code>AF</code> (Acknowledge Frame): Flusssteuerungs- und Bestätigungs-PDU der Gegenstelle.</li>\n<li><code>AF (Negative Acknowledge)</code>: NACK-Codierung im N-PCI; signalisiert Empfangs- oder Pufferungsfehler (z. B. temporäre Ressourcenerschöpfung).</li>\n<li><code>AF (Positive Acknowledge)</code>: ACK-Codierung im N-PCI; signalisiert den fehlerfreien Empfang und die Bereitstellung der Daten an die obere Schicht.</li>\n<li><strong>Stack-Schnittstellen (implizit beteiligt):</strong></li>\n<li>Obere Schicht (<code>PduR</code>): <code>PduR_FrArTpTxConfirmation()</code>, <code>PduR_FrArTpRxIndication()</code>.</li>\n<li>Untere Schicht (<code>FrIf</code>): <code>FrIf_Transmit()</code>, Bestätigung über <code>FrArTp_TxConfirmation()</code>, Empfang via <code>FrArTp_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Transfer (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender initiiert nach Erhalt einer Sendeanforderung (<code>FrArTp_Transmit</code>) die Übertragung einer unsegmentierten SDU mittels Single Frame (<code>SF</code>) über das FlexRay-Interface.</li>\n<li>Der Sender startet den Timeout-Timer für die Bestätigungserwartung (Timeout $A_s$ bzw. Bestätigungstimer).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfängerseitiger Fehler & NACK (<code>AF Negative Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger detektiert den <code>SF</code>, kann die Nachricht jedoch nicht ordnungsgemäß verarbeiten/puffern.</li>\n<li>Der Empfänger generiert einen <code>AF</code> mit negativem Statusflag (<code>Negative Acknowledge</code>) und sendet diesen an den Sender zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auswertung & Retransmission (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender empfängt die negative <code>AF</code>.</li>\n<li>Aufgrund der Moduskonfiguration <em>Acknowledgement with Retry</em> inkrementiert der Sender seinen internen Wiederholungszähler (Retry-Counter).</li>\n<li>Solange die maximale Anzahl konfigurierter Versuche (<code>FrArTpMaxRetries</code>) nicht überschritten ist, wird der identische <code>SF</code> erneut asynchron übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erfolgreiche Verarbeitung & Quittierung (<code>AF Positive Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger nimmt den retransmittierten <code>SF</code> an, puffert ihn erfolgreich und sendet eine <code>AF</code> mit positivem Bestätigungsstatus (<code>Positive Acknowledge</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender stoppt den Überwachungstimer und meldet den erfolgreichen Transfer mit <code>NTFRSLT_OK</code> an den <code>PduR</code>.</li>\n<li><em>Abbruchkriterium:</em> Scheitert auch der zweite (oder jeder weitere) Versuch und der Retry-Zähler erreicht das Limit (<code>FrArTpMaxRetries</code>), bricht der Sender die Übertragung ab und signalisiert der oberen Schicht einen Fehler (<code>NTFRSLT_E_NOT_OK</code> / Retry-Limit erreicht).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Pufferhaltung im Treiber/Stack:</strong></li>\n<li>Da der <code>Sender</code> bei konfigurierter Retry-Funktion die SDU nach einem NACK erneut senden muss, darf der Sendepuffer der oberen Schicht (<code>PduR</code>/Applikation) <strong>nicht</strong> direkt nach dem ersten <code>FrIf_Transmit()</code> bzw. dessen lokaler Bestätigung freigegeben werden. Der Puffer muss gebunden bleiben, bis entweder die positive <code>AF</code> empfangen wird oder die maximale Wiederholungsanzahl/der Timer erschöpft ist.</li>\n<li><strong>Konfigurationsparameter (ECUC):</strong></li>\n<li>Quittierungsmodus: <code>FrArTpAckType</code> = <code>ACK_WITH_RETRY</code> für die betroffene Verbindungsbeziehung (<code>FrArTpConnection</code>).</li>\n<li>Wiederholungsbegrenzung: <code>FrArTpMaxRetries</code> muss sorgfältig auf die Latenzanforderungen des Gesamtsystems abgestimmt werden, um Blockaden im Sendekanal zu vermeiden.</li>\n<li>Timer-Konfiguration: Abstimmung von Timeout-Parametern ($A_s$, $A_r$, $B_s$) auf das FlexRay-Kommunikationsraster (Cycle-Time, statisches/dynamisches Segment).</li>\n<li><strong>FlexRay-Slot- und Bandbreiten-Design:</strong></li>\n<li>Jede <code>AF</code> (insbesondere NACK gefolgt von erneutem SF und finaler ACK) belegt Bandbreite im FlexRay-Zyklus. Bei zyklischen PDUs kann eine Kette von NACKs und Retries zu Slot-Verzug (Jitter) und Pufferstau in der <code>FrArTp_MainFunction()</code> führen.</li>\n</ul>"}, {"id": "FIG-5a8b9f54c7296663", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm / Protokollablaufdiagramm (Message Sequence Chart) auf Transport-Layer-Ebene.</li>\n<li><strong>Architektur-Einordnung:</strong> Spezifikation des AUTOSAR Classic FlexRay AR Transport Layer (<code>FrArTp</code>, Schicht zwischen <code>PduR</code> und <code>FrIf</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des unsegmentierten 1:1-Punkt-zu-Punkt-Datentransfers (Unicast) unter der Betriebsart <em>„Acknowledgement with Retry“</em> bei primärem Übertragungsfehler. Dargestellt ist der Fehlertoleranzpfad: Ein initialer Fehler beim Empfänger führt zu einem NACK (<code>Negative Acknowledge</code>), woraufhin der Sender eine automatische Wiederholung (<code>SF</code>-Retransmission) ausführt, die mit einem ACK (<code>Positive Acknowledge</code>) quittiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsteilnehmer (Lifelines):</strong></li>\n<li><code>Sender</code>: Sende-Instanz des FlexRay AR Transport Layers (<code>FrArTp</code>).</li>\n<li><code>Receiver</code>: Empfangende Peer-Instanz des <code>FrArTp</code> auf der Ziel-ECU.</li>\n<li><strong>Protokoll-Dateneinheiten (N-PDUs / N-PCIs):</strong></li>\n<li><code>SF</code> (Single Frame): Unsegmentierte N-PDU. Enthält neben den Nutzdaten (SDU) den N-PCI-Header (Kennzeichnung als <code>SF</code> inklusive Datenlängenangabe).</li>\n<li><code>AF</code> (Acknowledge Frame): Flusssteuerungs- und Bestätigungs-PDU der Gegenstelle.</li>\n<li><code>AF (Negative Acknowledge)</code>: NACK-Codierung im N-PCI; signalisiert Empfangs- oder Pufferungsfehler (z. B. temporäre Ressourcenerschöpfung).</li>\n<li><code>AF (Positive Acknowledge)</code>: ACK-Codierung im N-PCI; signalisiert den fehlerfreien Empfang und die Bereitstellung der Daten an die obere Schicht.</li>\n<li><strong>Stack-Schnittstellen (implizit beteiligt):</strong></li>\n<li>Obere Schicht (<code>PduR</code>): <code>PduR_FrArTpTxConfirmation()</code>, <code>PduR_FrArTpRxIndication()</code>.</li>\n<li>Untere Schicht (<code>FrIf</code>): <code>FrIf_Transmit()</code>, Bestätigung über <code>FrArTp_TxConfirmation()</code>, Empfang via <code>FrArTp_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Transfer (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender initiiert nach Erhalt einer Sendeanforderung (<code>FrArTp_Transmit</code>) die Übertragung einer unsegmentierten SDU mittels Single Frame (<code>SF</code>) über das FlexRay-Interface.</li>\n<li>Der Sender startet den Timeout-Timer für die Bestätigungserwartung (Timeout $A_s$ bzw. Bestätigungstimer).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfängerseitiger Fehler & NACK (<code>AF Negative Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger detektiert den <code>SF</code>, kann die Nachricht jedoch nicht ordnungsgemäß verarbeiten/puffern.</li>\n<li>Der Empfänger generiert einen <code>AF</code> mit negativem Statusflag (<code>Negative Acknowledge</code>) und sendet diesen an den Sender zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auswertung & Retransmission (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender empfängt die negative <code>AF</code>.</li>\n<li>Aufgrund der Moduskonfiguration <em>Acknowledgement with Retry</em> inkrementiert der Sender seinen internen Wiederholungszähler (Retry-Counter).</li>\n<li>Solange die maximale Anzahl konfigurierter Versuche (<code>FrArTpMaxRetries</code>) nicht überschritten ist, wird der identische <code>SF</code> erneut asynchron übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erfolgreiche Verarbeitung & Quittierung (<code>AF Positive Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger nimmt den retransmittierten <code>SF</code> an, puffert ihn erfolgreich und sendet eine <code>AF</code> mit positivem Bestätigungsstatus (<code>Positive Acknowledge</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender stoppt den Überwachungstimer und meldet den erfolgreichen Transfer mit <code>NTFRSLT_OK</code> an den <code>PduR</code>.</li>\n<li><em>Abbruchkriterium:</em> Scheitert auch der zweite (oder jeder weitere) Versuch und der Retry-Zähler erreicht das Limit (<code>FrArTpMaxRetries</code>), bricht der Sender die Übertragung ab und signalisiert der oberen Schicht einen Fehler (<code>NTFRSLT_E_NOT_OK</code> / Retry-Limit erreicht).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Pufferhaltung im Treiber/Stack:</strong></li>\n<li>Da der <code>Sender</code> bei konfigurierter Retry-Funktion die SDU nach einem NACK erneut senden muss, darf der Sendepuffer der oberen Schicht (<code>PduR</code>/Applikation) <strong>nicht</strong> direkt nach dem ersten <code>FrIf_Transmit()</code> bzw. dessen lokaler Bestätigung freigegeben werden. Der Puffer muss gebunden bleiben, bis entweder die positive <code>AF</code> empfangen wird oder die maximale Wiederholungsanzahl/der Timer erschöpft ist.</li>\n<li><strong>Konfigurationsparameter (ECUC):</strong></li>\n<li>Quittierungsmodus: <code>FrArTpAckType</code> = <code>ACK_WITH_RETRY</code> für die betroffene Verbindungsbeziehung (<code>FrArTpConnection</code>).</li>\n<li>Wiederholungsbegrenzung: <code>FrArTpMaxRetries</code> muss sorgfältig auf die Latenzanforderungen des Gesamtsystems abgestimmt werden, um Blockaden im Sendekanal zu vermeiden.</li>\n<li>Timer-Konfiguration: Abstimmung von Timeout-Parametern ($A_s$, $A_r$, $B_s$) auf das FlexRay-Kommunikationsraster (Cycle-Time, statisches/dynamisches Segment).</li>\n<li><strong>FlexRay-Slot- und Bandbreiten-Design:</strong></li>\n<li>Jede <code>AF</code> (insbesondere NACK gefolgt von erneutem SF und finaler ACK) belegt Bandbreite im FlexRay-Zyklus. Bei zyklischen PDUs kann eine Kette von NACKs und Retries zu Slot-Verzug (Jitter) und Pufferstau in der <code>FrArTp_MainFunction()</code> führen.</li>\n</ul>"}, {"id": "FIG-79fa57a463362d3a", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm / Protokollablaufdiagramm (Message Sequence Chart) auf Transport-Layer-Ebene.</li>\n<li><strong>Architektur-Einordnung:</strong> Spezifikation des AUTOSAR Classic FlexRay AR Transport Layer (<code>FrArTp</code>, Schicht zwischen <code>PduR</code> und <code>FrIf</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des unsegmentierten 1:1-Punkt-zu-Punkt-Datentransfers (Unicast) unter der Betriebsart <em>„Acknowledgement with Retry“</em> bei primärem Übertragungsfehler. Dargestellt ist der Fehlertoleranzpfad: Ein initialer Fehler beim Empfänger führt zu einem NACK (<code>Negative Acknowledge</code>), woraufhin der Sender eine automatische Wiederholung (<code>SF</code>-Retransmission) ausführt, die mit einem ACK (<code>Positive Acknowledge</code>) quittiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsteilnehmer (Lifelines):</strong></li>\n<li><code>Sender</code>: Sende-Instanz des FlexRay AR Transport Layers (<code>FrArTp</code>).</li>\n<li><code>Receiver</code>: Empfangende Peer-Instanz des <code>FrArTp</code> auf der Ziel-ECU.</li>\n<li><strong>Protokoll-Dateneinheiten (N-PDUs / N-PCIs):</strong></li>\n<li><code>SF</code> (Single Frame): Unsegmentierte N-PDU. Enthält neben den Nutzdaten (SDU) den N-PCI-Header (Kennzeichnung als <code>SF</code> inklusive Datenlängenangabe).</li>\n<li><code>AF</code> (Acknowledge Frame): Flusssteuerungs- und Bestätigungs-PDU der Gegenstelle.</li>\n<li><code>AF (Negative Acknowledge)</code>: NACK-Codierung im N-PCI; signalisiert Empfangs- oder Pufferungsfehler (z. B. temporäre Ressourcenerschöpfung).</li>\n<li><code>AF (Positive Acknowledge)</code>: ACK-Codierung im N-PCI; signalisiert den fehlerfreien Empfang und die Bereitstellung der Daten an die obere Schicht.</li>\n<li><strong>Stack-Schnittstellen (implizit beteiligt):</strong></li>\n<li>Obere Schicht (<code>PduR</code>): <code>PduR_FrArTpTxConfirmation()</code>, <code>PduR_FrArTpRxIndication()</code>.</li>\n<li>Untere Schicht (<code>FrIf</code>): <code>FrIf_Transmit()</code>, Bestätigung über <code>FrArTp_TxConfirmation()</code>, Empfang via <code>FrArTp_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Transfer (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender initiiert nach Erhalt einer Sendeanforderung (<code>FrArTp_Transmit</code>) die Übertragung einer unsegmentierten SDU mittels Single Frame (<code>SF</code>) über das FlexRay-Interface.</li>\n<li>Der Sender startet den Timeout-Timer für die Bestätigungserwartung (Timeout $A_s$ bzw. Bestätigungstimer).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfängerseitiger Fehler & NACK (<code>AF Negative Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger detektiert den <code>SF</code>, kann die Nachricht jedoch nicht ordnungsgemäß verarbeiten/puffern.</li>\n<li>Der Empfänger generiert einen <code>AF</code> mit negativem Statusflag (<code>Negative Acknowledge</code>) und sendet diesen an den Sender zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auswertung & Retransmission (<code>SF</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender empfängt die negative <code>AF</code>.</li>\n<li>Aufgrund der Moduskonfiguration <em>Acknowledgement with Retry</em> inkrementiert der Sender seinen internen Wiederholungszähler (Retry-Counter).</li>\n<li>Solange die maximale Anzahl konfigurierter Versuche (<code>FrArTpMaxRetries</code>) nicht überschritten ist, wird der identische <code>SF</code> erneut asynchron übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erfolgreiche Verarbeitung & Quittierung (<code>AF Positive Acknowledge</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger nimmt den retransmittierten <code>SF</code> an, puffert ihn erfolgreich und sendet eine <code>AF</code> mit positivem Bestätigungsstatus (<code>Positive Acknowledge</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender stoppt den Überwachungstimer und meldet den erfolgreichen Transfer mit <code>NTFRSLT_OK</code> an den <code>PduR</code>.</li>\n<li><em>Abbruchkriterium:</em> Scheitert auch der zweite (oder jeder weitere) Versuch und der Retry-Zähler erreicht das Limit (<code>FrArTpMaxRetries</code>), bricht der Sender die Übertragung ab und signalisiert der oberen Schicht einen Fehler (<code>NTFRSLT_E_NOT_OK</code> / Retry-Limit erreicht).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Pufferhaltung im Treiber/Stack:</strong></li>\n<li>Da der <code>Sender</code> bei konfigurierter Retry-Funktion die SDU nach einem NACK erneut senden muss, darf der Sendepuffer der oberen Schicht (<code>PduR</code>/Applikation) <strong>nicht</strong> direkt nach dem ersten <code>FrIf_Transmit()</code> bzw. dessen lokaler Bestätigung freigegeben werden. Der Puffer muss gebunden bleiben, bis entweder die positive <code>AF</code> empfangen wird oder die maximale Wiederholungsanzahl/der Timer erschöpft ist.</li>\n<li><strong>Konfigurationsparameter (ECUC):</strong></li>\n<li>Quittierungsmodus: <code>FrArTpAckType</code> = <code>ACK_WITH_RETRY</code> für die betroffene Verbindungsbeziehung (<code>FrArTpConnection</code>).</li>\n<li>Wiederholungsbegrenzung: <code>FrArTpMaxRetries</code> muss sorgfältig auf die Latenzanforderungen des Gesamtsystems abgestimmt werden, um Blockaden im Sendekanal zu vermeiden.</li>\n<li>Timer-Konfiguration: Abstimmung von Timeout-Parametern ($A_s$, $A_r$, $B_s$) auf das FlexRay-Kommunikationsraster (Cycle-Time, statisches/dynamisches Segment).</li>\n<li><strong>FlexRay-Slot- und Bandbreiten-Design:</strong></li>\n<li>Jede <code>AF</code> (insbesondere NACK gefolgt von erneutem SF und finaler ACK) belegt Bandbreite im FlexRay-Zyklus. Bei zyklischen PDUs kann eine Kette von NACKs und Retries zu Slot-Verzug (Jitter) und Pufferstau in der <code>FrArTp_MainFunction()</code> führen.</li>\n</ul>"}], "trans": [{"from": "FIG-0e6c9c7c2c3b212a", "to": "FIG-3f16eccfd444835a", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3f16eccfd444835a", "to": "FIG-e39333f763ecaba8", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e39333f763ecaba8", "to": "FIG-ac649915c40bb616", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ac649915c40bb616", "to": "FIG-5a8b9f54c7296663", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5a8b9f54c7296663", "to": "FIG-79fa57a463362d3a", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
